import heapq
def dijkstra(e, cost_graph, n, init):

    heap = [(0, init)]
    used = []
    graph = {x: [] for x in range(len(e))}
    for edge in e:
        if edge[1] not in graph.keys():
            graph[edge[1]] = [(edge[2],edge[0] )]
        else:
            graph[edge[1]].append([edge[2],edge[0]])

    while heap:
        cost, cur = heapq.heappop(heap)

        if cur in used:
            continue
        used.append(cur)
        if cur == n-1:
            print(cost)
            heap = [(cost, i) for i in range(n)]
        for neighbord, cost in graph[cur]:
            if neighbord not in used:
                heap.append((cost+cost_graph[curr], neighbord))
            used.append(cur)
    if n-1 not in used:
        return -1
    return cost_graph[n-1]

