    for i in range(len(parent)):
        if i in parent:
            if i==source:
                return descendantsN*descendants2**i
            else:
                continue
        if i==source:
            continue
        temp=calculate_descentants(parent, source)
        temp= (2**temp)*descendants1**i
        descendantsN=descendants1*descendants2
        descendants2=descendantsN
        descendants1=temp
    return descendantsN*descendants2**i

