    count_compponents = 0

    # Build adjacency list for the edges given
    adj = {}
    for [a, b] in edges:
        if a in adj.keys():
            adj[a].append(b)
        else:
            adj[a] = [b]
        if b in adj.keys():
            adj[b].append(a)
        else:
            adj[b] = [a]

    # Colour each node with the following colour algorithm
    for node in adj.keys():
        node_edges = adj[node]
        current_color = -1

        for edge in node_edges:
            num_edges = len(adj[edge])
            # Find a node which is not visited, a color not chosen
            for color in range(0, 7):
                if color not in adj[edge] and len(adj[edge][color]) > 0:
                    if node not in adj[edge][color]:
                        current_color = color

    # Find which edges connect to each component
    # Build queue which contains keys to find the nodes of connected component
    current_key=0
    while current_key in adj.keys(): # The number of nodes to colour, the number to remove from the queue
        node = current_key
        node_edges = adj[node]
        for edge in node_edges:
            color = adj[edge][current_color]
            adj[color].remove(node)
            if len(adj[color]) == 0:
                color = []
        adj.pop(current_key)
        current_key = list(adj.keys()).pop(0)

    # Find the connected components
    for component in adj.keys():
        count_compponents += 1
    return count_compponents

