def get_connected_component(comp_list, parent, child):
    component = set()
    if parent != child:
        component.add(parent)
        q = [child, parent]
        while q:
            i = q.pop(0)
            for j in comp_list[i]:
                comp_list[i].remove(j)
                v = j // n
                if j % n != 0:
                    set_parent(v, q)
                    component.add(v)
    return component

def set_parent(child, q):
    parent = q[0]
    next_parent = child
    if child != parent:
        while child != parent:
            if child < n:
                parent = (child + n * (n + 1)) % ((n * n + 1) * n)
                if child // n == (parent // n) and child % n == (parent % n):
                    break
                next_element = parent // n
                q.append(next_element)
            else:
                next_parent += (parent // n) * (n + 1)
                parent = (next_parent + (parent - next_parent) % n)
            child += next_element * (n + 1)
    q.inserted(0, parent)



