def BFS(start: int):
    neighbours = adjacency()
    stack = [start]
    visited.append(stack.pop())
    while stack:
        current_node = stack[-1]
        neighbours = adjacency()
        visited.append(current_node)
        for node in neighbours:
            if node not in visited and visited[-2] not in node:
                stack.append(current_node)
            if visited[-2] in node:
                stack.append(node)

    return neighbours

