    if path_start == path_end and grid[path_start[0]][path_start[1]] == '.':
        return [path_start]

    if path_start[0] not in range(row) or path_start[1] not in range(col) or grid[path_start[0]][path_start[1]] == '#':
        return None # invalid start (out of range, is #)

    if path_start in memoization_table and path_end not in memoization_table[path_start[0]]:
        return memoization_table[path_start[0]][path_start[1]]

    possible_cells = []
    if path_start[0] - 1 >= 0 and grid[path_start[0]-1][path_start[1]] != '#':
        possible_cells.append((path_start[0]-1, path_start[1]))

