        possible_cells.append((path_start[0], path_start[1]-1))

    if path_start[1] + 1 < col and grid[path_start[0]][path_start[1]+1] != '#':
        possible_cells.append((path_start[0], path_start[1]+1))

    cell = None
    for y in possible_cells:
        for n in y:
            path = solve_helper(row, col, grid, y, path_end, memoization_table)
