def binarySearch(nums):
    lo = 1
    hi = len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[mid+1] or nums[mid-1] == nums[mid] or nums[mid] == nums[mid-1]:
            return nums[mid]
        if nums[mid] < nums[mid+1]:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

