def convert_to_int_with_carry(x,y):
    carry = x + y
    if carry >= 10:
        return carry * 10 + (carry // 10) * (1 - 10)
    else:
        return carry

def convert_to_bigint(dec):
    result = 0
    base = 0
    result_int = 0
    while dec > 0: 
        result_int = convert_to_int_with_carry(result, dec % 10)
        result = result_int + base * 10 
        dec = dec // 10
        base = base * 10
    return result

