def initializeMatrix(n):
    matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            if j == i:
                row.append(1)
            else:
                row.append(0)
        matrix.append(row)
    return matrix

def buildEdgeList(graph, prerequisites):
    edgeList = []
    for k in range(len(prerequisites)):
        a, b = prerequisites[k]
        rowB = graph[b]
        rowA = graph[a]
        nonNullIndexB = 0
        nonNullIndexA = 0
        for i in range(len(rowB)):
            if rowB[i] == 1:
                nonNullIndexB = i
                break
        for j in range(len(rowA)):
            if rowA[j] == 1:
                nonNullIndexA = j
                break
        else:
            return []
        if nonNullIndexB >= nonNullIndexA:
            edgeList.append([nonNullIndexA, nonNullIndexB])
        else:
            edgeList.append([nonNullIndexB, nonNullIndexA])
    return edgeList

def topoSort(edgeList, graph):
    vis = [False for _ in range(len(graph))]
    path = []
    for i in range(len(edgeList)):
        if (not vis[edgeList[i][0]]):
            path = dfs(edgeList, vis, graph, path, edgeList[i][0])
            vis[edgeList[i][0]] = True
            return path
    return path

