    """Given n, learn to order n nodes and maintain a edge order"""

    def construct(dependencies, level = 0, name = 0):
	"""construct an order by level and DFS"""

        if level == n:
            return {name: -level}
        ordered = {} 
        for child in range(name + 1, n):
            sub = dict(dependencies[child][1:])
            children = construct(sub, level = level + 1, name = child)
            required = []
            for parent in dependencies[child][0]:
                if not children.has_key(parent):
                    required.append(parent)
            # construct a child's ordered dependent list
            if not required:
                ordered.update(children)
            else:
                ordered.update(dict(parent = [parent] * len(required),
                          child = children,
                          dependents = required,
                          children = None))
        ordered.update(dict(parent = [name], child = children))
        return ordered



