def dfs(v, oldSet):
    """Solve the problem using depth-first-search to find all subsets of v and how deep on the recursion tree it is returning some solution."""

# Use it in main()

    ''' uses DFS approach. returns an empty list if problem invalid. '''

    taskList = [[] for x in range(n)]
    hasTask = [False for x in range(n)]

    order = [-1 for x in range(n)]

    # construct graph and find in-degree of tasks
    for task in prerequisites:
        taskList[task[1]].append(task[0])
        hasTask[task[0]] = True
        if task[0] not in order:
            order[task[0]] = -1

    # initialize graph and order as valid solution
    # return solution if none hasTask=False
    if not any(hasTask):
        return [(x, -1) for x in order]

    # perform dfs on task with min in-degree with highest order value
    in_degree = {}
    for task in prerequisites:
        if task in in_degree:
            in_degree[task] += 1
        else:
            in_degree[task] = 1

    stack = [index for index, task in enumerate(order) if task==-1]

    while stack:
        current_task = stack.pop()
        taskId = order[current_task] = len(stack)
        order[current_task] = taskId
        # prevent cycle
        if taskId in order:
            if taskId == len(stack):
                return []
            else:
                return []

        if current_task in order:
            # perform backtracking to find valid solution
            index = order[current_task]
            while index >= 0:
                if hasTask[index]:
                    order[index] = index + 1
                    order[current_task] = index
                    stack.append(index)
                    if hasTask[index]:
                        hasTask[index] = False
                index -= 1

    return [(x, -1) for x in order]

