    if upper_bound < lower:
        return -1
    mid= lower + ((upper_bound - lower) // 2)
    if nums[mid] == target:
        return lower 
    elif nums[mid] > target:
        return binary_search(nums, target, lower, mid-1)
    else:
        return binary_search(nums, target, mid + 1, upper_bound)

