def find_first(numbers, number_to_find, start = 0, end = len(numbers)-1):
    if start == end:
        return -1 if numbers[start] != number_to_find else start
    else:
        middle = start + int((end - start)/2)
        if (numbers[middle] <= number_to_find and middle > 0 and numbers[middle-1] > number_to_find):
            return middle - 1
        elif (numbers[middle] < number_to_find and middle): 
            return find_first(numbers, number_to_find, middle, end)
        elif numbers[middle] >= number_to_find:
            return find_first(numbers, number_to_find, start, middle)
        elif numbers[middle] > number_to_find:
            return find_first(numbers, number_to_find, middle, end)

def find_last(index_of_first_occurrence, numbers, number_to_find, start = 0, end = len(numbers)-1):
        if start > end:
            return index_of_first_occurrence
        middle = start + int((end - start)/2)
        if index_of_first_occurrence > middle:
            return find_last(index_of_first_occurrence, numbers, number_to_find, start, middle-1)
        else:
            return find_last(index_of_first_occurrence, numbers, number_to_find, middle, end)

