        out = sorted(nums, key=d.get, reverse=True)[:currentLength]

        nextOut = out[k:]
        if len(nextOut) == 0: return out, len(out)

        if nextOut[0] == out[0]:
            out = select(nums[nums.index(nextOut[0]):], 1)[0]   # getting rid of duplicates
            while len(out) != len(nextOut): # removing the values returned from this func
                out.remove(nextOut[len(nextOut)])            
        else:
           nextOut = select(nums[1:], len(out))[0]
           out = list(set(out + nextOut))
        return out, len(out)

