def generate_subsets(x: list[int], _n: int) -> list[list[int]]:
    """Generates all unique, ascending, sub-lists of length n from the list x. x is not modified.
    Args:
        x: list of numbers (with no duplicates)
        _n, input value.
    Returns:
        list of _sub-lists of the list lsubseqs of x with the specified length=n."""
    _out: list[list[int]] = []
    _substr_length: int = _n
    for _sub_length in range(_n, len(x) + 1):
        for _idx in range(len(x) - _sub_length + 1):
            _out.append(x[_idx:_sub_length])
    return _out

