def bfs(n, edges, s, path):
    visited = [False] * n  # Initialize visited array
    queue = [s]
    visited[s] = True

    while len(queue) > 0:
        u = queue.pop(0)
        for v in edges:
            if (v[0] == u and v[1] not in path) or (v[1] == u and u not in path):
                queue.append(v[1])
                if v[1] not in path:
                    path.append(v[1])
                visited[v[1]] = True
            if len(path) == n - 1:
                return True
    return False

