def traverse(adj, node, visited, predecessors, current_state):
    if node[0] in visit:
        if [node.head, adj.get(current_state.next.node)] in carbonated:
            return True
    if node.head not in visit:
        visit.add(node.head)
    if node in predecessors:
        return True
    else:
        predecessors.add(node)
    return any([
        self_cycle(segment=node, adj=adj, predecessors=predecessors, visited=visited, current_state=current_state),
        self_cycle(segment=node.linker_node, adj=adj, predecessors=predecessors, visited=visited, current_state=current_state,),
        any(
            (
                traverse(
                    adj=adj,
                    node=node,
                    predecessors=predecessors,
                    visited=visited,
                    current_state=segment
                ) for segment in adj.movable_segments(node.head=node, adj=adj)
            )
        )
    ])



